          "type": "string"
        },
        "decisions": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "incomingItemId": {
                "type": "string"
              },
              "decision": {
                "type": "string"
              },
              "reason": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
